catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    var subcategory = g_form.getControl('subcategory');
    if (!subcategory) {
        return;
    }

    // Clear existing options
    g_form.clearOptions('subcategory');

    if (newValue == 'software') {
        g_form.addOption('subcategory', 'functionality_issues', 'Functionality Issues');
        g_form.addOption('subcategory', 'compatibility_problems', 'Compatibility Problems');
        g_form.addOption('subcategory', 'security_problems', 'Security Problems');
        g_form.addOption('subcategory', 'license_issues', 'License Issues');
        g_form.addOption('subcategory', 'user_interface', 'User Interface');
    } else if (newValue == 'hardware') {
        g_form.addOption('subcategory', 'physical_damages', 'Physical Damages');
        g_form.addOption('subcategory', 'component_failures', 'Component Failures');
        g_form.addOption('subcategory', 'peripheral_devices', 'Peripheral Devices');
        g_form.addOption('subcategory', 'network_connectivity', 'Network and Connectivity Problems');
        g_form.addOption('subcategory', 'power_supply', 'Power Supply');
    }
}
